// Frozen independent D1 archive bytes, with the accepted unit1 receipt5 envelope.
// Only the envelope's declared synthetic producer input/artifact pins and imported
// source-read pins were rebound to the actual retained archive bytes. Candidate,
// helper and external provenance remain synthetic/unapproved. No production
// validator or preparation function generates this fixture.
func catalogRetainedFixture(t *testing.T) (Receipt, map[string][]byte) {
	t.Helper()
	compressed, err := base64.StdEncoding.DecodeString(catalogFrozen48)
	if err != nil {
		t.Fatal(err)
	}
	gz, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		t.Fatal(err)
	}
	b, err := io.ReadAll(io.LimitReader(gz, 2<<20))
	if err != nil {
		t.Fatal(err)
	}
	gz.Close()
	var fixture struct {
		Receipt Receipt           `json:"receipt"`
		Payload map[string]string `json:"payload"`
	}
	if err = json.Unmarshal(b, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Payload) != 48 {
		t.Fatal("frozen48 closure")
	}
	data := map[string][]byte{}
	for p, b := range fixture.Payload {
		data[p] = []byte(b)
	}
	return fixture.Receipt, data
}
func stageCatalogFixture(t *testing.T, s *Store, r Receipt, data map[string][]byte) (Inspection, error) {
	t.Helper()
	tx, err := s.begin()
	if err != nil {
		return Inspection{}, err
	}
	defer tx.close()
	if _, err = tx.validate(); err != nil {
		return Inspection{}, recovery(err)
	}
	return tx.stageGeneration(r, data, func() error { return nil })
}
func mustCatalogFixture(t *testing.T, s *Store) Inspection {
	t.Helper()
	r, data := catalogRetainedFixture(t)
	got, err := stageCatalogFixture(t, s, r, data)
	if err != nil {
		t.Fatal(err)
	}
	if got.TrustLabel != catalogTrustLabel {
		t.Fatal("catalog approval leaked", got.TrustLabel)
	}
	return got
}
func TestCatalogRetainedFrozen48ReaderAndIdentity(t *testing.T) {
	r, data := catalogRetainedFixture(t)
	rb, err := canonjson.MarshalFile(r)
	if err != nil {
		t.Fatal(err)
	}
	if err = author.ValidateCatalogDocumentEncoding(author.CatalogReceipt5, rb); err != nil {
		t.Fatal(err)
	}
	var decoded Receipt
	if err = strictJSON(rb, &decoded, true); err != nil {
		t.Fatal(err)
	}
	round, err := canonjson.MarshalFile(decoded)
	if err != nil || !bytes.Equal(rb, round) {
		t.Fatal("receipt5 byte identity", err)
	}
	s := mustOpen(t)
	got, err := stageCatalogFixture(t, s, r, data)
	if err != nil {
		t.Fatal(err)
	}
	if got.GenerationID != digest(rb) || got.TrustLabel != catalogTrustLabel {
		t.Fatal("retained inert identity")
	}
	for _, op := range []func() (Inspection, error){s.Inspect, s.Recover} {
		next, err := op()
		if err != nil || next.GenerationID != got.GenerationID || next.TrustLabel != catalogTrustLabel {
			t.Fatal(next, err)
		}
	}
	for p, want := range data {
		actual, err := os.ReadFile(filepath.Join(s.root, "generations", got.GenerationID, p))
		if err != nil || !bytes.Equal(want, actual) {
			t.Fatal(p, err)
		}
	}
	t.Log("actual closed48 private copy, receipt hash, inspection and recovery; optional empty fragments retained")
}
func TestCatalogMixedHistoryRollbackImmutable(t *testing.T) {
	repo, commit := fixture(t, "catalog mixed history")
	s := mustOpen(t)
	v1 := mustStage(t, s, repo, commit)
	v2 := installSyntheticV2(t, s).GenerationID
	prior := installSyntheticV2Payload(t, s, func(r *Receipt, _ map[string][]byte) {
		r.Policy.UpstreamCommit = "33cb805b5482d511071be7b344140e2ccb8c87da"
		r.Policy.UpstreamTree = "3439bd874573cb88bbad852c5b66771f2ab80eeb"
	}).GenerationID
	v5 := mustCatalogFixture(t, s)
	snapshots := map[string][]byte{}
	for _, id := range []string{v1.GenerationID, prior, v2, v5.GenerationID} {
		b, err := os.ReadFile(filepath.Join(s.root, "generations", id, "receipt.json"))
		if err != nil {
			t.Fatal(err)
		}
		snapshots[id] = b
	}
	for _, id := range []string{v1.GenerationID, prior, v2, v5.GenerationID, v2, prior, v1.GenerationID} {
		got, err := s.SelectPrior(id)
		if err != nil || got.GenerationID != id {
			t.Fatal(got, err)
		}
		for old, want := range snapshots {
			actual, err := os.ReadFile(filepath.Join(s.root, "generations", old, "receipt.json"))
			if err != nil || !bytes.Equal(actual, want) || digest(actual) != old {
				t.Fatal("historical receipt changed", err)
			}
		}
	}
	t.Log("mixed v1/v2/receipt5 offline rollback preserves all receipt bytes and immutable IDs")
}
func catalogFixtureObject(t *testing.T, r Receipt) map[string]any {
	t.Helper()
	b, err := canonjson.MarshalFile(r)
	if err != nil {
		t.Fatal(err)
	}
	v, err := canonjson.DecodeObject(b)
	if err != nil {
		t.Fatal(err)
	}
	return v
}
func TestCatalogReceiptClosedEnvelopeMutations(t *testing.T) {
	r, _ := catalogRetainedFixture(t)
	base := catalogFixtureObject(t, r)
	for _, object := range []string{"", "catalog", "policy", "guidance"} {
		target := base
		if object != "" {
			target = retainedObject(base[object])
		}
		for key := range target {
			for _, mutation := range []string{"missing", "null", "duplicate"} {
				t.Run(object+"/"+key+"/"+mutation, func(t *testing.T) {
					v := catalogFixtureObject(t, r)
					m := v
					if object != "" {
						m = retainedObject(v[object])
					}
					var b []byte
					if mutation == "missing" {
						delete(m, key)
					} else if mutation == "null" {
						m[key] = nil
					}
					b, _ = canonjson.MarshalFile(v)
					if mutation == "duplicate" {
						needle := []byte(canonjson.EscapeASCII(key) + ":")
						pos := bytes.Index(b, needle)
						b = append(append(append([]byte{}, b[:pos]...), []byte(canonjson.EscapeASCII(key)+": null,\n")...), b[pos:]...)
					}
					var got Receipt
					if strictJSON(b, &got, true) == nil {
						t.Fatal("closed receipt accepted")
					}
				})
			}
		}
	}
	for _, mutate := range []func(map[string]any){
		func(v map[string]any) { v["schema_version"] = json.Number("3") },
		func(v map[string]any) { v["schema_version"] = json.Number("4") },
		func(v map[string]any) { retainedObject(v["catalog"])["derivation"] = "upkeeper-tool-overlay-v3" },
		func(v map[string]any) { retainedObject(retainedArray(v["files"])[0])["mode"] = json.Number("384") },
		func(v map[string]any) { retainedObject(retainedArray(v["files"])[0])["kind"] = "guidance-input" },
		func(v map[string]any) { retainedObject(retainedArray(v["files"])[0])["path"] = "../unsafe" },
		func(v map[string]any) { a := retainedArray(v["files"]); a[0], a[1] = a[1], a[0] },
		func(v map[string]any) { v["files"] = retainedArray(v["files"])[1:] },
		func(v map[string]any) { a := retainedArray(v["files"]); v["files"] = append(a, a[0]) },
		func(v map[string]any) {
			retainedObject(v["source_sha256"])["shared/catalog-guidance/guidance/huyang.json"] = strings.Repeat("b", 64)
		},
	} {
		v := catalogFixtureObject(t, r)
		mutate(v)
		b, _ := canonjson.MarshalFile(v)
		var got Receipt
		if strictJSON(b, &got, true) == nil {
			t.Fatal("catalog metadata mutation accepted")
		}
	}
	// New omitempty fields must not expand historical shapes, even with null.
	for _, version := range []int{1, 2} {
		old, _ := syntheticV2Payload(t, nil)
		old.SchemaVersion = version
		if version == 1 {
			old.Policy = nil
		}
		v := catalogFixtureObject(t, old)
		for _, key := range []string{"catalog", "guidance"} {
			v[key] = nil
			b, _ := canonjson.MarshalFile(v)
			var got Receipt
			if strictJSON(b, &got, true) == nil {
				t.Fatal("historical new field accepted")
			}
			delete(v, key)
		}
	}
}

// Rebind only declared receipt pins to changed private retained test bytes.
// This is test-only and cannot provide production source/preparation provenance.
func catalogRebindFixture(t *testing.T, r *Receipt, data map[string][]byte, path string) {
	t.Helper()
	old := ""
	for _, f := range r.Files {
		if f.Path == path {
			old = f.SHA256
		}
	}
	next := digest(data[path])
	v := catalogFixtureObject(t, *r)
	var replace func(any)
	replace = func(x any) {
		switch x := x.(type) {
		case map[string]any:
			for k, e := range x {
				if e == old {
					x[k] = next
				} else {
					replace(e)
				}
			}
		case []any:
			for i, e := range x {
				if e == old {
					x[i] = next
				} else {
					replace(e)
				}
			}
		}
	}
	replace(v)
	g := retainedObject(v["guidance"])
	g["projection_sha256"] = retainedHash(g["projection"])
	b, _ := canonjson.MarshalFile(v)
	if err := json.Unmarshal(b, r); err != nil {
		t.Fatal(err)
	}
	if err := author.ValidateCatalogDocumentEncoding(author.CatalogReceipt5, b); err != nil {
		t.Fatal("mutation did not retain admitted receipt metadata", err)
	}
}
func TestCatalogContainedBytesRefuseDespiteReboundHashes(t *testing.T) {
	cases := []struct {
		name, path string
		change     func(map[string]any)
	}{
		{"profile observation", "inputs/guidance-profile.json", func(v map[string]any) { retainedObject(v["evidence"])["sha256"] = strings.Repeat("b", 64) }},
		{"manifest catalog", "inputs/tool-guidance-manifest.json", func(v map[string]any) { v["catalog_sha256"] = strings.Repeat("b", 64) }},
		{"observation source", "inputs/guidance-observation.json", func(v map[string]any) {
			f := retainedObject(retainedArray(retainedObject(retainedObject(v["source_reads"])["data"])["files"])[0])
			f["content"] = retainedString(f["content"]) + "changed\n"
		}},
		{"producer input", "inputs/tool-producer-receipt.json", func(v map[string]any) { v["input_sha256"] = strings.Repeat("b", 64) }},
		{"layout reference", "inputs/guidance-layout.json", func(v map[string]any) {
			retainedObject(v["bindings"])["operational_reference_sha256"] = strings.Repeat("b", 64)
		}},
		{"menu record", "metadata/guidance/menu.json", func(v map[string]any) {
			retainedObject(retainedObject(retainedArray(v["tools"])[0])["catalog_record"])["purpose"] = "wrong purpose"
		}},
		{"package owner", "inputs/tool-guidance/huyang.json", func(v map[string]any) { retainedObject(v["owner"])["source_sha256"] = strings.Repeat("b", 64) }},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			r, data := catalogRetainedFixture(t)
			v, err := canonjson.DecodeObject(data[c.path])
			if err != nil {
				t.Fatal(err)
			}
			c.change(v)
			data[c.path], _ = canonjson.MarshalFile(v)
			catalogRebindFixture(t, &r, data, c.path)
			s := mustOpen(t)
			got, err := stageCatalogFixture(t, s, r, data)
			if err == nil || got.GenerationID != "" {
				t.Fatal("metadata-only acceptance", err)
			}
		})
	}
}
func TestCatalogPhysicalClosureAndMutation(t *testing.T) {
	mutations := map[string]func(*testing.T, string){
		"missing": func(t *testing.T, p string) {
			if err := os.Remove(p); err != nil {
				t.Fatal(err)
			}
		},
		"extra": func(t *testing.T, p string) {
			if err := os.WriteFile(filepath.Join(filepath.Dir(p), "extra"), []byte("extra"), 0644); err != nil {
				t.Fatal(err)
			}
		},
		"empty directory": func(t *testing.T, p string) {
			if err := os.Mkdir(filepath.Join(filepath.Dir(p), "extra"), 0700); err != nil {
				t.Fatal(err)
			}
		},
		"mode": func(t *testing.T, p string) {
			if err := os.Chmod(p, 0600); err != nil {
				t.Fatal(err)
			}
		},
		"special mode": func(t *testing.T, p string) {
			if err := os.Chmod(p, os.ModeSetuid|0644); err != nil {
				t.Fatal(err)
			}
		},
		"symlink": func(t *testing.T, p string) {
			if err := os.Remove(p); err != nil {
				t.Fatal(err)
			}
			if err := os.Symlink("absent", p); err != nil {
				t.Fatal(err)
			}
		},
		"hardlink": func(t *testing.T, p string) {
			if err := os.Link(p, p+".link"); err != nil {
				t.Fatal(err)
			}
		},
		"fifo": func(t *testing.T, p string) {
			if err := os.Remove(p); err != nil {
				t.Fatal(err)
			}
			if err := syscall.Mkfifo(p, 0644); err != nil {
				t.Fatal(err)
			}
		},
		"hash": func(t *testing.T, p string) {
			if err := os.WriteFile(p, []byte("changed"), 0644); err != nil {
				t.Fatal(err)
			}
		},
		"nul": func(t *testing.T, p string) {
			if err := os.WriteFile(p, []byte{0}, 0644); err != nil {
				t.Fatal(err)
			}
		},
		"oversize text": func(t *testing.T, p string) {
			if err := os.WriteFile(p, bytes.Repeat([]byte("x"), 65537), 0644); err != nil {
				t.Fatal(err)
			}
		},
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			s := mustOpen(t)
			got := mustCatalogFixture(t, s)
			p := filepath.Join(s.root, "generations", got.GenerationID, ".config/agents/huyang.md")
			mutate(t, p)
			for _, op := range []func() (Inspection, error){s.Inspect, s.Recover, func() (Inspection, error) { return s.SelectPrior(got.GenerationID) }} {
				if _, err := op(); !errors.Is(err, ErrRecoveryRequired) {
					t.Fatal("corruption did not refuse", err)
				}
			}
		})
	}
	for _, path := range []string{"inputs/guidance-observation.json", "metadata/guidance/fragments/fixture-mcp.md", ".config/agents/huyang.md"} {
		t.Run("read mutation/"+path, func(t *testing.T) {
			s := mustOpen(t)
			got := mustCatalogFixture(t, s)
			changed := false
			s.h.afterRead = func(p string) {
				if p == path && !changed {
					changed = true
					out := filepath.Join(s.root, "generations", got.GenerationID, path)
					if err := os.WriteFile(out, []byte("mutated"), 0600); err != nil {
						t.Fatal(err)
					}
				}
			}
			if _, err := s.Inspect(); err == nil || !changed {
				t.Fatal("held descriptor mutation accepted", err)
			}
		})
	}
}
func TestCatalogRetainedBoundsAndUnselectedHistory(t *testing.T) {
	for _, path := range []string{"inputs/guidance-layout.json", "inputs/guidance-observation.json", ".config/agents/huyang.md"} {
		t.Run(path, func(t *testing.T) {
			r, data := catalogRetainedFixture(t)
			n := 65537
			if path == "inputs/guidance-layout.json" {
				n = 131073
			}
			if path == "inputs/guidance-observation.json" {
				n = 262145
			}
			data[path] = bytes.Repeat([]byte("x"), n)
			// The text reference is also help-bound; mutate only the input cases'
			// receipt pins so the physical size test precedes content validation.
			if strings.HasPrefix(path, "inputs/") {
				catalogRebindFixture(t, &r, data, path)
			}
			s := mustOpen(t)
			if got, err := stageCatalogFixture(t, s, r, data); err == nil || got.GenerationID != "" {
				t.Fatal("oversize retained payload accepted", err)
			}
		})
	}
	s := mustOpen(t)
	catalog := mustCatalogFixture(t, s)
	old := installSyntheticV2(t, s)
	if _, err := s.SelectPrior(old.GenerationID); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(s.root, "generations", catalog.GenerationID, "metadata/guidance/fragments/fixture-mcp.md")
	if err := os.WriteFile(path, []byte("extra"), 0644); err != nil {
		t.Fatal(err)
	}
	for _, op := range []func() (Inspection, error){s.Inspect, s.Recover, func() (Inspection, error) { return s.SelectPrior(old.GenerationID) }} {
		if _, err := op(); !errors.Is(err, ErrRecoveryRequired) {
			t.Fatal("unselected catalog corruption ignored", err)
		}
	}
}
