func TestCatalogRetainedInputClosedSchemas(t *testing.T) {
	_, data := catalogRetainedFixture(t)
	schemas := map[string]string{
		"inputs/tool-guidance-manifest.json": "tool_guidance_manifest_v1",
		"inputs/guidance-profile.json":       "guidance_profile_v1",
		"inputs/guidance-observation.json":   "guidance_observation_v1",
		"inputs/guidance-layout.json":        "layout_v4",
		"inputs/required-global-policy.json": "required_global_policy_v1",
		"inputs/tool-catalog.json":           "catalog_v1",
		"inputs/tool-producer-input.json":    "producer_input_v1",
		"inputs/tool-producer-receipt.json":  "producer_receipt_v1",
		"inputs/tool-guidance/huyang.json":   "tool_guidance_v1",
		"metadata/guidance/menu.json":        "guidance_menu_v1",
	}
	for path, schema := range schemas {
		t.Run(path, func(t *testing.T) {
			if _, err := retainedDecode(data[path], schema, metadataLimit); err != nil {
				t.Fatal(err)
			}
			pristine, err := canonjson.DecodeObject(data[path])
			if err != nil {
				t.Fatal(err)
			}
			for key := range pristine {
				for _, mutation := range []string{"unknown", "missing", "null"} {
					v, _ := canonjson.DecodeObject(data[path])
					switch mutation {
					case "unknown":
						v["unknown"] = true
					case "missing":
						delete(v, key)
					case "null":
						v[key] = nil
					}
					b, _ := canonjson.MarshalFile(v)
					if _, err := retainedDecode(b, schema, metadataLimit); err == nil {
						t.Fatalf("%s/%s accepted", key, mutation)
					}
				}
			}
		})
	}
}
func TestCatalogPartialPayloadAndParentSubstitution(t *testing.T) {
	for _, parent := range []bool{false, true} {
		s := mustOpen(t)
		r, data := catalogRetainedFixture(t)
		tx, err := s.begin()
		if err != nil {
			t.Fatal(err)
		}
		got, err := tx.stageGeneration(r, data, func() error {
			names, e := os.ReadDir(filepath.Join(s.root, "incomplete"))
			if e != nil || len(names) != 1 {
				t.Fatal("stage evidence", e)
			}
			root := filepath.Join(s.root, "incomplete", names[0].Name())
			path := filepath.Join(root, ".config/agents/huyang.md")
			if parent {
				dir := filepath.Dir(path)
				if e = os.Rename(dir, dir+".held"); e != nil {
					t.Fatal(e)
				}
				if e = os.Mkdir(dir, 0700); e != nil {
					t.Fatal(e)
				}
			} else if e = os.Truncate(path, 1); e != nil {
				t.Fatal(e)
			}
			return nil
		})
		tx.close()
		if err == nil || got.GenerationID != "" {
			t.Fatal("partial/substituted stage selected", err)
		}
		if _, err = s.Recover(); !errors.Is(err, ErrRecoveryRequired) {
			t.Fatal("corrupt evidence adopted", err)
		}
		if _, err = os.Readlink(filepath.Join(s.root, "candidate-current")); !os.IsNotExist(err) {
			t.Fatal("selector changed", err)
		}
	}
}
func TestCatalogEveryTransactionFaultDurabilityAndRestart(t *testing.T) {
	r, data := catalogRetainedFixture(t)
	baseline := mustOpen(t)
	events := []string{}
	baseline.h.event = func(p string) { events = append(events, normalize(p)) }
	if _, err := stageCatalogFixture(t, baseline, r, data); err != nil {
		t.Fatal(err)
	}
	seen := map[string]bool{}
	for _, boundary := range events {
		if seen[boundary] {
			continue
		}
		seen[boundary] = true
		t.Run(boundary, func(t *testing.T) {
			s := mustOpen(t)
			before := lockInode(t, s.root)
			hit := false
			s.h.fault = func(p string) error {
				if normalize(p) == boundary && !hit {
					hit = true
					return errors.New("catalog injected I/O failure")
				}
				return nil
			}
			got, err := stageCatalogFixture(t, s, r, data)
			if !hit || err == nil || got.GenerationID != "" {
				t.Fatal("false durable success", boundary, err)
			}
			// Retained incomplete evidence must never be adopted, deleted or overwritten.
			stages, _ := os.ReadDir(filepath.Join(s.root, "incomplete"))
			names := []string{}
			for _, e := range stages {
				names = append(names, e.Name())
			}
			reopened, err := Open(s.root)
			if err == nil {
				_, err = reopened.Recover()
			}
			if len(names) > 0 && !errors.Is(err, ErrRecoveryRequired) {
				t.Fatal("incomplete evidence adopted", err)
			}
			for _, n := range names {
				if _, e := os.Stat(filepath.Join(s.root, "incomplete", n)); e != nil {
					t.Fatal("incomplete evidence lost", e)
				}
			}
			if !sameInode(before, lockInode(t, s.root)) {
				t.Fatal("persistent lock replaced")
			}
		})
	}
	for _, required := range []string{"fsync:incomplete-finalization", "fsync:generations-finalization", "fsync:selection"} {
		if !seen[required] {
			t.Fatal("missing fault boundary", required)
		}
	}
	t.Logf("catalog transaction actual write/sync/rename/restart boundaries: %d", len(seen))
}

